package org.apache.commons.lang.time;

import junit.framework.TestCase;
import java.util.Calendar;
import java.util.Date;

public class AgentBRT_Lang_65_ast_edit_Test extends TestCase {

    public void testReproduceBug() {
        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.OCTOBER, 16, 10, 30, 0); // Set a date at the start of the second half of the month
        calendar.set(Calendar.MILLISECOND, 0);

        // Convert Calendar to Date
        Date date = calendar.getTime();

        // Attempt to truncate to SEMI_MONTH
        Date truncatedDate = DateUtils.truncate(date, DateUtils.SEMI_MONTH);

        // Expected behavior: The date should be truncated to the start of the second semi-month period
        Calendar expectedCalendar = Calendar.getInstance();
        expectedCalendar.set(2023, Calendar.OCTOBER, 16, 0, 0, 0);
        expectedCalendar.set(Calendar.MILLISECOND, 0);

        assertEquals("The date should be truncated to the start of the second semi-month period",
                     expectedCalendar.getTime(), truncatedDate);
    }
}

